import type { ReactNode } from 'react';
import React, { forwardRef } from 'react';
import { FormattedMessage } from 'react-intl';
import styled from 'styled-components';

import Animations from '@dynatrace/strato-design-tokens/animations';
import Borders from '@dynatrace/strato-design-tokens/borders';
import Colors from '@dynatrace/strato-design-tokens/colors';
import Spacings from '@dynatrace/strato-design-tokens/spacings';
import Typography from '@dynatrace/strato-design-tokens/typography';

import { _useControllableState } from '../../core/hooks/useControllableState.js';
import {
  useFocusRing,
  CSSFocusStylesObject,
} from '../../core/hooks/useFocusRing.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import { WithChildren } from '../../core/types/with-children.js';
import { uuidv4 } from '../../core/utils/uuidv4.js';
// #region Typings
export interface ExpandableTextBaseProps
  extends WithChildren,
    StylingProps,
    DataTestId {
  /**
   * Text shown for expanding the content.
   * @defaultValue 'Show more'
   */
  expandLabel?: ReactNode;
  /**
   * Text shown for collapsing the content.
   * @defaultValue 'Show less'
   */
  collapseLabel?: ReactNode;
}

export interface ExpandableTextUncontrolledProps {
  /**
   * Determines whether or not the content is initially expanded in an uncontrolled scenario.
   * @defaultValue false
   */
  defaultExpanded?: boolean;
  /**
   * Determines whether or not the content is expanded in a controlled scenario.
   */
  expanded?: never;
  /**
   * Callback fired when the expanded attribute changes in a controlled scenario.
   */
  onExpandChange?: never;
}

export interface ExpandableTextControlledProps {
  /**
   * Determines whether or not the content is initially expanded in an uncontrolled scenario.
   */
  defaultExpanded?: never;
  /**
   * Determines whether or not the content is expanded in a controlled scenario.
   */
  expanded: boolean;
  /**
   * Callback fired when the expanded attribute changes in a controlled scenario.
   */
  onExpandChange: (expanded: boolean) => void;
}

/** Accepted properties for ExpandableText */
export type ExpandableTextProps = ExpandableTextBaseProps &
  (ExpandableTextControlledProps | ExpandableTextUncontrolledProps);

// #endregion Typings

// #region StyledComponents
const StyledExpandableText = /* @__PURE__ */ styled('span')<{
  isExpanded: boolean;
}>(({ isExpanded }) => ({
  opacity: isExpanded ? 1 : 0,
  transition: `opacity ${Animations.ExpandCollapse.Duration.Fast} ${Animations.ExpandCollapse.Easing}`,
}));

const StyledExpandButton = /* @__PURE__ */ styled('button')<{
  $focusStyle?: CSSFocusStylesObject;
  $isFocusVisible?: boolean;
}>(({ $focusStyle, $isFocusVisible }) => ({
  border: 'none',
  borderRadius: Borders.Radius.Field.Subdued,
  background: 'transparent',
  color: Colors.Text.Neutral.Default,
  padding: Spacings.Size0,
  paddingInline: Spacings.Size2,
  fontWeight: Typography.Text.Base.Default.Weight,
  fontFamily: Typography.Text.Base.Default.Family,
  lineHeight: 'inherit',
  fontSize: 'inherit',
  cursor: 'pointer',
  outline: 'none',
  textDecoration: 'underline',
  textDecorationStyle: 'dashed',
  textUnderlineOffset: Spacings.Size4,
  textDecorationThickness: Borders.Width.Default,
  textDecorationColor: Colors.Border.Neutral.Accent,
  transition: `background-color ${Animations.Hover.Duration.Base} ${Animations.Hover.Easing}`,

  '&:hover': {
    background: Colors.Background.Field.Neutral.DefaultHover,
  },
  '&:active': {
    background: Colors.Background.Field.Neutral.DefaultActive,
  },
  ...$focusStyle,
  ...($isFocusVisible && {
    textDecoration: 'none',
  }),
}));
// #endregion StyledComponents

/** The `ExpandableText` component provides expand and collapse functionality for inline text. */
export const ExpandableText = forwardRef<HTMLElement, ExpandableTextProps>(
  (props, forwardedRef) => {
    const {
      children,
      style: consumerStyle,
      className: consumerClassName,
      'data-testid': dataTestId,
      expandLabel = (
        <FormattedMessage
          description="Shown for expandable text."
          defaultMessage="Show more"
          id="DV3d5lBJda+EHJja"
        />
      ),
      collapseLabel = (
        <FormattedMessage
          description="Shown for collapsible text."
          defaultMessage="Show less"
          id="986buSbL34GVFlBf"
        />
      ),
      defaultExpanded = false,
      expanded,
      onExpandChange,
    } = props;

    const { focusStyles, focusProps, isFocusVisible } = useFocusRing({
      variant: 'neutral',
      isMinimal: true,
    });

    const [isExpanded, setExpanded] = _useControllableState({
      defaultValue: defaultExpanded,
      value: expanded,
      onChange: onExpandChange,
    });

    const textId = `expandable-${uuidv4()}`;

    return (
      <>
        <StyledExpandableText
          ref={forwardedRef}
          isExpanded={isExpanded}
          id={textId}
          role="region"
          data-testid={dataTestId}
          className={consumerClassName}
          style={consumerStyle}
        >
          {isExpanded && ' '}
          {isExpanded && children}
        </StyledExpandableText>{' '}
        <StyledExpandButton
          onClick={() => setExpanded(!isExpanded)}
          aria-controls={textId}
          aria-expanded={isExpanded}
          $focusStyle={focusStyles}
          $isFocusVisible={isFocusVisible}
          {...focusProps}
        >
          {isExpanded ? collapseLabel : expandLabel}
        </StyledExpandButton>
      </>
    );
  },
);
